{
  "headline": "Prioritize indoor air and mask use today",
  "summary": "Air quality is {{level.name}} with current AQI {{aqi.now}}. Reducing outdoor exposure from {{exposure.before}} to {{exposure.after}} is key. The best outdoor window is {{best.start}} to {{best.end}}.",
  "cards": [
    {
      "actionId": "diy_box_fan_filter",
      "title": "Build a DIY box fan air filter",
      "why": "A DIY filter can significantly reduce indoor PM2.5 levels by {{impact.diy_box_fan_filter.pct}}.",
      "when": "Set up and run continuously indoors.",
      "steps": [
        "Attach a MERV-13 filter to a box fan.",
        "Ensure a good seal around the filter edges.",
        "Run the fan on a medium setting."
      ]
    },
    {
      "actionId": "exercise_indoors_when_poor",
      "title": "Move exercise indoors",
      "why": "Exercising indoors avoids inhaling high concentrations of PM2.5, reducing exposure by {{impact.exercise_indoors_when_poor.pct}}.",
      "when": "Whenever air quality is {{level.name}} or worse.",
      "steps": [
        "Engage in indoor workouts or yoga.",
        "Ensure good ventilation in your exercise space if possible."
      ]
    },
    {
      "actionId": "n95_for_open_transport",
      "title": "Wear an N95 mask for open transport",
      "why": "An N95 mask provides excellent protection, reducing inhaled particles by {{impact.n95_for_open_transport.pct}} during commutes.",
      "when": "For any travel on public transport or open vehicles.",
      "steps": [
        "Ensure the mask has a snug fit.",
        "Wear it throughout the journey, including waiting times."
      ]
    },
    {
      "actionId": "carpool_shared_ride",
      "title": "Consider carpooling or shared rides",
      "why": "Carpooling reduces the number of vehicles on the road, contributing to lower overall emissions.",
      "when": "For regular commutes or group travel.",
      "steps": [
        "Coordinate with neighbors or colleagues.",
        "Use ride-sharing apps for efficient travel."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for no burning in the community",
      "why": "Community-wide efforts to stop burning can lead to substantial air quality improvements.",
      "when": "Ongoing advocacy and discussion.",
      "steps": [
        "Talk to neighbors about the impact of burning.",
        "Engage with your Resident Welfare Association (RWA)."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Limit outdoor play to when air quality is better, or ensure they wear a mask if outdoors."
    },
    {
      "group": "senior",
      "note": "Advise seniors to minimize time spent outdoors and avoid strenuous activity."
    },
    {
      "group": "respiratory",
      "note": "Individuals with respiratory conditions should be extra cautious and stay indoors as much as possible."
    }
  ],
  "tradeoffs": [
    "Wearing an N95 mask on public transport is essential to mitigate increased exposure.",
    "Carpooling reduces traffic but requires coordination and may involve shared spaces."
  ]
}
